import{_ as i,o as a,c as r,ae as t}from"./chunks/framework.DFTT1zkb.js";const p=JSON.parse('{"title":"入学准备","description":"","frontmatter":{},"headers":[],"relativePath":"begin/preparation.md","filePath":"begin/preparation.md"}'),o={name:"begin/preparation.md"};function e(n,l,s,u,h,c){return a(),r("div",null,[...l[0]||(l[0]=[t('<h1 id="入学准备" tabindex="-1">入学准备 <a class="header-anchor" href="#入学准备" aria-label="Permalink to &quot;入学准备&quot;">​</a></h1><h2 id="必备" tabindex="-1">必备 <a class="header-anchor" href="#必备" aria-label="Permalink to &quot;必备&quot;">​</a></h2><ul><li><strong>录取通知书</strong></li><li><strong>身份证</strong></li><li><strong>证件照</strong><ul><li>推荐使用小二寸蓝底照片</li><li>尽管大部分情况下对照片背景颜色没有要求，但是你可以各种颜色都备一点</li><li>你也可以保存电子档照片，需要之时再前往校内打印店打印</li></ul></li><li><strong>学籍档案</strong><ul><li>你也可以选择参照新生手册中的步骤邮寄至学校</li></ul></li><li><strong>团员档案</strong>（非团员不用） <ul><li>团员证</li><li>团组织关系介绍信</li><li>团员档案袋</li></ul></li><li><strong>贫困证明材料</strong>（如果需要）</li></ul><h2 id="必要能力" tabindex="-1">必要能力 <a class="header-anchor" href="#必要能力" aria-label="Permalink to &quot;必要能力&quot;">​</a></h2><h3 id="反诈能力" tabindex="-1">反诈能力 <a class="header-anchor" href="#反诈能力" aria-label="Permalink to &quot;反诈能力&quot;">​</a></h3><p>详见<a href="./anti_fraud.html">谨防诈骗</a></p><h3 id="独立生活" tabindex="-1">独立生活 <a class="header-anchor" href="#独立生活" aria-label="Permalink to &quot;独立生活&quot;">​</a></h3><p>包括但不限于自己去食堂吃饭、洗衣服、打扫卫生、生病时如何养护自己等</p><p>有的同学可能在初高中阶段均为走读，几乎从未离开家长的怀抱，独立生活能力相对较差，因此在暑假期间务必准备好适应没有家长保驾护航的生活</p><h3 id="最基础的礼貌用语" tabindex="-1">最基础的礼貌用语 <a class="header-anchor" href="#最基础的礼貌用语" aria-label="Permalink to &quot;最基础的礼貌用语&quot;">​</a></h3><p>用好礼貌用语可以避免对方感到不适，同时给人留下更好的第一印象</p><h3 id="查找资料" tabindex="-1">查找资料 <a class="header-anchor" href="#查找资料" aria-label="Permalink to &quot;查找资料&quot;">​</a></h3><p>有时你可能需要找学校发布的官方文件、导员很早之前发过的通知或一些学习资料，但是总是会发现不是找不到就是找的不是想要的</p><h4 id="qq-等聊天软件内" tabindex="-1">QQ 等聊天软件内 <a class="header-anchor" href="#qq-等聊天软件内" aria-label="Permalink to &quot;QQ 等聊天软件内&quot;">​</a></h4><ul><li>直接在首页的搜索栏输入<mark>关键词</mark>查找聊天记录</li><li>看看精华消息、群公告和群文件？说不定导员很早就发过了</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>在向辅导员求助询问前务必按以上方法先查找一遍，可以避免不必要的时间浪费和麻烦</p></div><h4 id="官网通知" tabindex="-1">官网通知 <a class="header-anchor" href="#官网通知" aria-label="Permalink to &quot;官网通知&quot;">​</a></h4><p>推荐使用<a href="https://cn.bing.com/" target="_blank" rel="noreferrer">必应</a>搜索</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>为什么不是<s>百度/搜狗/360 好问</s>等其他搜索引擎</strong></p><ol><li>其他搜索引擎广告非常多</li><li>其他搜索引擎准确度远低于必应</li><li>必应的非中文搜索功能做的更好，这在搜索国外网站时很有帮助</li></ol></div><h3 id="制作-ppt" tabindex="-1">制作 PPT <a class="header-anchor" href="#制作-ppt" aria-label="Permalink to &quot;制作 PPT&quot;">​</a></h3><p>竞选班委、小组作业、答辩时常用到</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>你可以借助<a href="https://www.doubao.com/" target="_blank" rel="noreferrer">豆包</a>、<a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi</a>等 ai 工具</p></div><h2 id="必要物品" tabindex="-1">必要物品 <a class="header-anchor" href="#必要物品" aria-label="Permalink to &quot;必要物品&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>开学前夕快递站常爆满，且校外附近几乎没有驿站，如需邮寄请做好准备</li><li>部分用品可在学校超市购买，不一定需要全部从家里带来</li><li>加粗项为强烈推荐准备的物品，其他的按需选择</li></ul></div><h3 id="洗护用品" tabindex="-1">洗护用品 <a class="header-anchor" href="#洗护用品" aria-label="Permalink to &quot;洗护用品&quot;">​</a></h3><ul><li><strong>牙具</strong></li><li><strong>毛巾+浴巾</strong></li><li>洗发水+护发素</li><li>沐浴露</li><li><strong>脸盆</strong></li><li>暖壶</li><li><strong>洗面奶/香皂</strong></li><li><strong>洗衣皂/洗洁精/洗衣粉/洗衣液</strong></li><li>鞋刷</li></ul><h3 id="宿舍相关用品" tabindex="-1">宿舍相关用品 <a class="header-anchor" href="#宿舍相关用品" aria-label="Permalink to &quot;宿舍相关用品&quot;">​</a></h3><ul><li><strong>纸巾/卫生纸</strong></li><li><strong>衣服</strong><ul><li>冬夏外套+各种衣服</li><li>石家庄冷热分明，所以要准备好夏季短袖、短裤和冬季秋裤、棉裤、羽绒服</li></ul></li><li><strong>拖鞋</strong></li><li>衣架</li><li>夹子 <ul><li>晒被子时候防止被吹走</li></ul></li><li>晾衣杆</li><li><strong>垃圾桶+垃圾袋</strong></li><li>镜子</li><li>梳子</li><li><strong>插排</strong><ul><li>宿舍插口有限且位置偏僻，必须自带插排</li></ul></li><li><strong>锁</strong></li><li><strong>台灯</strong><ul><li>能充电的最好</li></ul></li><li><strong>指甲剪</strong></li><li>螺丝刀+小锤子+钳子</li><li>剪刀+小刀 <ul><li>过不了安检！！！</li></ul></li><li>抹布 + 扫把 + 拖把 <ul><li>开学时每个宿舍会发放，但非常不好用，最好还是自己买一套好点的</li></ul></li></ul><h3 id="床上用品" tabindex="-1">床上用品 <a class="header-anchor" href="#床上用品" aria-label="Permalink to &quot;床上用品&quot;">​</a></h3><p>宿舍床的尺寸：<strong>1.9m*0.9m</strong></p><p>一定要慎重考虑床品，这关系到你未来四年的生活质量，切勿轻信贩卖床品的人</p><ul><li><p><strong>床垫</strong></p><ul><li>床上只有一个木板没有床垫哦</li></ul></li><li><p>枕头、棉被/薄被、毯子</p><ul><li>学校不发放，需自行购买</li></ul></li></ul><h3 id="军训用品" tabindex="-1">军训用品 <a class="header-anchor" href="#军训用品" aria-label="Permalink to &quot;军训用品&quot;">​</a></h3><ul><li><strong>防晒用品</strong><ul><li><s>厨邦酱油美味鲜，晒足 180 天。你看就在这儿晒。这是地大军训大晒场，有图有真相，就在这儿晒</s></li></ul></li><li><strong>水瓶</strong><ul><li>若没有可以去超市买 1.5L 的矿泉水，一般来说男生半天就能喝一桶</li></ul></li><li><strong>质量好点的鞋垫</strong><ul><li>军训期间需要一直站立，对自己的脚好一点咯</li></ul></li></ul><h3 id="食品相关" tabindex="-1">食品相关 <a class="header-anchor" href="#食品相关" aria-label="Permalink to &quot;食品相关&quot;">​</a></h3><ul><li>家乡特产 <ul><li>和舍友打好关系啦~</li></ul></li><li>泡面碗</li><li>筷子</li><li>削皮刀、水果刀</li><li>勺子</li></ul><h3 id="出行小装备" tabindex="-1">出行小装备 <a class="header-anchor" href="#出行小装备" aria-label="Permalink to &quot;出行小装备&quot;">​</a></h3><ul><li><strong>雨伞</strong>+遮阳伞</li><li><strong>包</strong><ul><li>大大小小的，自己看着办</li></ul></li><li>钥匙扣 <ul><li>挂宿舍和抽屉钥匙用</li></ul></li><li>自行车 <ul><li>学校内有自行车停车位，但不允许开自己的电动车</li></ul></li><li><strong>行李箱</strong></li></ul><h3 id="电子产品相关" tabindex="-1">电子产品相关 <a class="header-anchor" href="#电子产品相关" aria-label="Permalink to &quot;电子产品相关&quot;">​</a></h3><ul><li><p><strong>平板/电脑</strong></p><ul><li>大学期间有许多任务需要电脑完成，包括但不限于 PPT 制作、视频剪辑、填写资料表格、工图建模</li><li>选工科的同学建议选择 Windows 系统的电脑，否则部分工科软件很难或无法运行</li><li>大一上学期绝大部分课程没有需要自带电脑的，因此不着急购买，但大一下学期部分专业的部分课程有自带电脑的需求，因此推荐在6.18或双11选购电脑</li><li>电脑配置按自己的游戏性能选购即可，目前主流电脑大部分都可以带动课堂要求的软件</li></ul></li><li><p><strong>充电器/数据线</strong></p></li><li><p>台灯</p></li><li><p><strong>充电宝</strong></p></li></ul>',40)])])}const g=i(o,[["render",e]]);export{p as __pageData,g as default};
